// 6-job_processor.js
import kue from 'kue';

const queue = kue.createQueue(); // Connexion à Redis par défaut

function sendNotification(phoneNumber, message) {
  console.log(`Sending notification to ${phoneNumber}, with message: ${message}`);
}

